export const MIN_FREQUENCY_HZ = 1;
export const MAX_FREQUENCY_HZ = 30000;
export const FREQUENCY_SLIDER_STEPS = 3000;
export const MAX_FREQUENCY_EXPANSIONS = 12;
export const HARMONIC_INTERVALS = [
  { type: 'third', name: '大三度', numerator: 5, denominator: 4, multiplier: 1.25 },
  { type: 'fourth', name: '纯四度', numerator: 4, denominator: 3, multiplier: 1.4 },
  { type: 'fifth', name: '纯五度', numerator: 3, denominator: 2, multiplier: 1.5 },
  { type: 'octave', name: '纯八度', numerator: 2, denominator: 1, multiplier: 2 }
];

export function clampFrequencyHz(value, fallback = 440) {
  const frequency = Number(value);
  if (!Number.isFinite(frequency)) return fallback;
  return Math.max(MIN_FREQUENCY_HZ, Math.min(MAX_FREQUENCY_HZ, frequency));
}

export function frequencyLimitForExpansion(level) {
  const parsedLevel = Number(level);
  const expansions = Number.isFinite(parsedLevel)
    ? Math.max(0, Math.min(MAX_FREQUENCY_EXPANSIONS, Math.floor(parsedLevel)))
    : 0;
  return Math.min(MAX_FREQUENCY_HZ, 10 * 2 ** expansions);
}

export function frequencyFromSlider(value, maximum = MAX_FREQUENCY_HZ) {
  const maximumHz = clampFrequencyHz(maximum);
  const position = Math.max(0, Math.min(FREQUENCY_SLIDER_STEPS, Number(value) || 0))
    / FREQUENCY_SLIDER_STEPS;
  return MIN_FREQUENCY_HZ * (maximumHz / MIN_FREQUENCY_HZ) ** position;
}

export function sliderFromFrequency(value, maximum = MAX_FREQUENCY_HZ) {
  const maximumHz = clampFrequencyHz(maximum);
  if (maximumHz === MIN_FREQUENCY_HZ) return 0;
  const frequency = Math.min(maximumHz, clampFrequencyHz(value));
  return Math.round(
    Math.log(frequency / MIN_FREQUENCY_HZ)
    / Math.log(maximumHz / MIN_FREQUENCY_HZ)
    * FREQUENCY_SLIDER_STEPS
  );
}

export function formatFrequencyHz(value) {
  const frequency = clampFrequencyHz(value);
  if (frequency < 100) return `${Number(frequency.toFixed(2))} Hz`;
  if (frequency < 1000) return `${Math.round(frequency)} Hz`;
  return `${Math.round(frequency).toLocaleString('en-US')} Hz`;
}

export function getFrequencyBand(value) {
  const frequency = clampFrequencyHz(value);
  if (frequency <= 20) return '次声波';
  if (frequency >= 20000) return '超声波';
  return '可听声波';
}

export function getFrequencyProfile(value) {
  const band = getFrequencyBand(value);
  if (band === '次声波') {
    return { band, propagation: 1.12, resonanceToleranceCents: 60, planetReward: 1.25 };
  }
  if (band === '超声波') {
    return { band, propagation: 0.72, resonanceToleranceCents: 15, planetReward: 1.5 };
  }
  return { band, propagation: 1, resonanceToleranceCents: 35, planetReward: 1 };
}

export function legacySliderFrequency(value, fallback = 440) {
  const slider = Number(value);
  if (!Number.isFinite(slider)) return fallback;
  const position = Math.max(0, Math.min(100, slider)) / 100;
  return MIN_FREQUENCY_HZ * (MAX_FREQUENCY_HZ / MIN_FREQUENCY_HZ) ** position;
}

export function getResonanceTargets(reference, maximum = MAX_FREQUENCY_HZ) {
  const maximumHz = clampFrequencyHz(maximum);
  const frequency = Math.min(maximumHz, clampFrequencyHz(reference));
  return HARMONIC_INTERVALS.map(interval => {
    const higher = frequency * interval.numerator / interval.denominator;
    const lower = frequency * interval.denominator / interval.numerator;
    const inverted = higher > maximumHz;
    const target = inverted ? lower : higher;
    return {
      ...interval,
      ratioLabel: inverted
        ? `${interval.denominator}:${interval.numerator}`
        : `${interval.numerator}:${interval.denominator}`,
      frequency: Math.min(maximumHz, clampFrequencyHz(target))
    };
  });
}
