import { GameEngine, getFrequencyRelation, loadLegacyState } from './engine.js';
import { translate } from './i18n.js';
import { formatFrequencyHz, frequencyFromSlider, FREQUENCY_SLIDER_STEPS, sliderFromFrequency } from './frequency.js';
import { WaveformRenderer } from './waveform.js';
import { createSaveFile, loadSave, parseSaveFile, SAVE_KEY, LEGACY_SAVE_KEY, writeSave } from './storage.js';
import { SoundEffects } from './audio.js';
import { renderNavigation, renderPanel, updateCore, updateResources } from './ui.js';

const $ = selector => document.querySelector(selector);
const sound = new SoundEffects();
let activeView = 'upgrades';
let toastTimeout;
let spaceEmitInterval;
let lastSpaceEmit = 0;
let engine;
let waveform;

try {
  const { state, migrated } = loadSave();
  engine = new GameEngine(state);
  if (migrated) writeSave(engine);
} catch (error) {
  console.error('Unable to load the Cry & Bright save.', error);
  engine = new GameEngine(loadLegacyState(null));
  showToast('存档读取失败，已启动新进度。');
}

applyTheme(engine.state.theme);
document.documentElement.lang = engine.state.language;
waveform = new WaveformRenderer($('#wave-viewport'), $('#wave-canvas'));
renderStaticLocale();
renderNavigation(activeView, engine.state.language, engine.state.eternalLevel);
renderPanel(engine, activeView);
renderEverything();

if (engine.state.language !== 'en-US' && engine.state.stats.emitted === 0) {
  showToast('欢迎来到鸣与明。');
}

function renderStaticLocale() {
  const language = engine.state.language;
  document.documentElement.lang = language;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    element.textContent = translate(element.dataset.i18n, language);
  });
  document.title = language === 'en-US' ? 'Cry & Bright — Listen to the shape of the universe' : 'Cry & Bright — 鸣与明';
  $('#frequency-slider').setAttribute('aria-label', translate('频率', language));
  $('#frequency-input').setAttribute('aria-label', translate('输入精确频率', language));
  $('#view-navigation').setAttribute('aria-label', translate('游戏面板', language));
  $('#wave-canvas').setAttribute('aria-label', translate('实时回声波形', language));
}

function applyTheme(theme) {
  document.body.dataset.theme = theme;
  $('meta[name="theme-color"]').content = getComputedStyle(document.body).getPropertyValue('--page').trim();
}

function renderEverything() {
  updateResources(engine);
  updateCore(engine, waveform);
  const activeChains = engine.activeChains(true);
  const selfOnly = activeChains.length === 1 && activeChains[0].frequency === engine.state.frequency;
  const relation = selfOnly ? null : activeChains.reduce((best, chain) => {
    const result = getFrequencyRelation(engine.state.frequency, chain.frequency, engine.state.interferenceBoost);
    if (result.type === 'interference') return result;
    return result.multiplier > (best?.multiplier || 1) ? result : best;
  }, null);
  const relationLabels = {
    interference: '干涉',
    octave: '纯八度',
    fifth: '纯五度',
    third: '大三度',
    fourth: '纯四度',
    neutral: '等待信号'
  };
  $('#signal-frequency').textContent = formatFrequencyHz(engine.state.frequency).replace(' Hz', '');
  $('#footer-frequency').textContent = formatFrequencyHz(engine.state.frequency).replace(' Hz', '');
  $('#signal-global').textContent = `×${engine.globalMultiplier().toFixed(2)}`;
  const relationLabel = translate(relationLabels[relation?.type || 'neutral'], engine.state.language);
  $('#signal-relation').textContent = relation
    ? `${relationLabel} ×${relation.multiplier}`
    : relationLabel;
  $('#signal-relation').dataset.relation = relation?.type || 'neutral';
  $('#signal-meter span').style.width = `${sliderFromFrequency(engine.state.frequency, engine.getFrequencyLimit()) / FREQUENCY_SLIDER_STEPS * 100}%`;
}

function playSound(frequency, duration = 0.16, volume = 0.035) {
  if (engine.state.soundEnabled) sound.play(frequency, duration, volume);
}

function refreshPanel() {
  renderNavigation(activeView, engine.state.language, engine.state.eternalLevel);
  renderPanel(engine, activeView);
}

function showToast(message) {
  const toast = $('#toast');
  toast.textContent = translate(message, engine?.state.language || 'zh-CN');
  toast.classList.add('visible');
  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => toast.classList.remove('visible'), 2600);
}

function persist() {
  try {
    writeSave(engine);
  } catch (error) {
    console.error('Unable to save Cry & Bright progress.', error);
    showToast('存档失败，请检查浏览器本地存储设置。');
  }
}

function emitWave() {
  if (!engine.emit(engine.state.frequency)) return false;
  playSound(Math.max(100, Math.min(1600, engine.state.frequency)), 0.18);
  const button = $('#emit-button');
  button.classList.remove('is-emitting');
  void button.offsetWidth;
  button.classList.add('is-emitting');
  renderEverything();
  persist();
  return true;
}

function stopSpaceEmission() {
  clearInterval(spaceEmitInterval);
  spaceEmitInterval = undefined;
}

function actionButton(action, element) {
  switch (action) {
    case 'emit':
      emitWave();
      return;
    case 'ability':
      if (engine.activateAbility(element.dataset.id)) playSound(220, 0.28);
      break;
    case 'buy-upgrade':
      if (engine.buyUpgrade(element.dataset.id)) playSound(380, 0.12);
      else showToast('资源不足。');
      break;
    case 'buy-soundscape':
      if (engine.buySoundscape(Number(element.dataset.index))) playSound(260, 0.28);
      else showToast('资源不足。');
      break;
    case 'unlock-source':
      if (engine.unlockSource(Number(element.dataset.index))) playSound(480, 0.18);
      else showToast('资源不足。');
      break;
    case 'buy-prestige':
      if (engine.buyPermanentUpgrade(element.dataset.id)) playSound(520, 0.16);
      else showToast('资源不足。');
      break;
    case 'buy-relic':
      if (engine.buyRelic(element.dataset.id)) playSound(700, 0.2);
      else showToast('资源不足。');
      break;
    case 'lock-planet':
      engine.lockPlanet();
      break;
    case 'advance-tier':
      if (!window.confirm(translate('确认推进层级？这将清空当轮资源、声源、声场与普通升级。', engine.state.language))) return;
      if (!engine.advanceTier()) {
        break;
      }
      activeView = 'expedition';
      playSound(760, 0.6, 0.05);
      break;
    case 'prestige':
      if (engine.state.silence < engine.getFinalCost()) {
        engine.prestige();
        break;
      }
      if (window.confirm(translate('确认长明？这将重置当前轮回进度。', engine.state.language))) {
        const level = engine.state.eternalLevel + 1;
        if (engine.prestige()) {
          activeView = 'prestige';
          showToast(`${translate('长明完成', engine.state.language)} · Lv.${level}`);
          playSound(620, 0.8, 0.06);
        }
      }
      break;
    case 'toggle-sound':
      engine.state.soundEnabled = !engine.state.soundEnabled;
      break;
    case 'export-save':
      exportSave();
      return;
    case 'import-save':
      $('#import-file').click();
      return;
    case 'hard-reset':
      if (!window.confirm(translate('确定清空所有存档与成就？', engine.state.language))) return;
      engine.hardReset();
      activeView = 'upgrades';
      try {
        localStorage.removeItem(SAVE_KEY);
        localStorage.removeItem(LEGACY_SAVE_KEY);
      } catch (error) {
        console.error('Unable to clear Cry & Bright save.', error);
      }
      break;
    default:
      return;
  }
  refreshPanel();
  renderEverything();
  persist();
}

function exportSave() {
  const url = URL.createObjectURL(createSaveFile(engine));
  const link = document.createElement('a');
  link.href = url;
  link.download = `cry-bright-save-${new Date().toISOString().slice(0, 10)}.json`;
  link.click();
  URL.revokeObjectURL(url);
  showToast('存档已导出。');
}

async function importSave(file) {
  if (!file) return;
  try {
    const imported = parseSaveFile(await file.text());
    engine = new GameEngine(imported);
    applyTheme(engine.state.theme);
    activeView = 'upgrades';
    renderStaticLocale();
    refreshPanel();
    renderEverything();
    persist();
    showToast('存档导入成功。');
  } catch (error) {
    console.error('Unable to import Cry & Bright save.', error);
    showToast('存档文件无效。');
  }
  $('#import-file').value = '';
}

document.addEventListener('click', event => {
  const resonanceTarget = event.target.closest('[data-frequency-target]');
  if (resonanceTarget) {
    engine.state.frequency = Math.min(engine.getFrequencyLimit(), Number(resonanceTarget.dataset.frequencyTarget));
    renderEverything();
    persist();
    return;
  }
  const viewButton = event.target.closest('[data-view]');
  if (viewButton) {
    activeView = viewButton.dataset.view;
    refreshPanel();
    return;
  }
  const action = event.target.closest('[data-action]');
  if (action) actionButton(action.dataset.action, action);
});

$('#frequency-slider').addEventListener('input', event => {
  engine.state.frequency = frequencyFromSlider(event.target.value, engine.getFrequencyLimit());
  renderEverything();
});

document.addEventListener('input', event => {
  const input = event.target.closest('[data-source-frequency]');
  if (!input) return;
  const source = engine.state.sources[Number(input.dataset.sourceFrequency)];
  if (!source?.unlocked) return;
  source.frequency = frequencyFromSlider(input.value, engine.getFrequencyLimit());
  input.previousElementSibling.querySelector('output').value = formatFrequencyHz(source.frequency);
  persist();
});

document.addEventListener('change', event => {
  if (event.target.id === 'frequency-input') {
    const frequency = Math.floor(Number(event.target.value));
    if (!Number.isFinite(frequency) || frequency < 1 || frequency > engine.getFrequencyLimit()) {
      showToast('请输入 1 到当前频率上限之间的频率。');
      event.target.value = String(Math.floor(engine.state.frequency));
      renderEverything();
      return;
    }
    engine.state.frequency = frequency;
    event.target.value = String(frequency);
    renderEverything();
    persist();
  } else if (event.target.id === 'theme-select') {
    engine.state.theme = event.target.value;
    applyTheme(event.target.value);
    waveform.resize();
    renderEverything();
    persist();
  } else if (event.target.id === 'language-select') {
    engine.state.language = event.target.value;
    renderStaticLocale();
    refreshPanel();
    renderEverything();
    persist();
  } else if (event.target.id === 'import-file') {
    importSave(event.target.files?.[0]);
  }
});

document.addEventListener('keydown', event => {
  if (event.code !== 'Space' || event.target.closest('button, input, select, textarea, [contenteditable="true"]')) return;
  event.preventDefault();
  if (spaceEmitInterval) return;
  if (!emitWave()) return;
  lastSpaceEmit = performance.now();
  spaceEmitInterval = setInterval(() => {
    if (performance.now() - lastSpaceEmit < 180) return;
    lastSpaceEmit = performance.now();
    if (!emitWave()) stopSpaceEmission();
  }, 50);
});

window.addEventListener('keyup', event => {
  if (event.code === 'Space') stopSpaceEmission();
});
window.addEventListener('blur', stopSpaceEmission);
window.addEventListener('beforeunload', persist);

let last = performance.now();
let uiElapsed = 0;
let saveElapsed = 0;
function frame(now) {
  const delta = Math.min((now - last) / 1000, 0.1);
  last = now;
  engine.update(delta);
  for (const event of engine.drainEvents()) {
    if (event.type === 'achievement') showToast(`✦ ${translate(event.name, engine.state.language)}`);
    else if (event.type === 'silence') showToast(`◍ +${event.amount.toFixed(1)} ${translate('暗寂', engine.state.language)}`);
    else if (event.type === 'tier') showToast(`${translate(event.name, engine.state.language)} · ${translate('信标已点亮', engine.state.language)}`);
    else if (event.type === 'discovery') showToast(`✦ ${translate('深空发现', engine.state.language)}：${translate(event.name, engine.state.language)}`);
    else if (event.type === 'planet-detected') showToast('发现新的行星回波，已加入航线扫描。');
    else if (event.type === 'planet-locked') showToast('已锁定行星固有频率，调谐后再次发波以尝试谐振。');
    else if (event.type === 'planet-miss') showToast('频率尚未进入共振容差。');
    else if (event.type === 'planet-resonance') showToast(`行星谐振解构 · +${event.echo.toFixed(0)} ${translate('鸣响', engine.state.language)} · +${event.silence.toFixed(1)} ${translate('暗寂', engine.state.language)}`);
    else if (event.type === 'story') {
      showToast(`▤ ${translate(event.title, engine.state.language)}`);
      if (activeView === 'story') renderPanel(engine, activeView);
      persist();
    }
    else if (event.type === 'notice') showToast(event.key);
  }
  waveform.render(engine);
  uiElapsed += delta;
  if (uiElapsed >= 0.12) {
    uiElapsed = 0;
    updateResources(engine);
    updateCore(engine, waveform);
    const current = $('#signal-frequency');
    if (current) current.textContent = formatFrequencyHz(engine.state.frequency).replace(' Hz', '');
    const footer = $('#footer-frequency');
    if (footer) footer.textContent = formatFrequencyHz(engine.state.frequency).replace(' Hz', '');
  }
  saveElapsed += delta;
  if (saveElapsed >= 5) {
    saveElapsed = 0;
    persist();
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
